from fractions import Fraction


def von_neumann(flips):
    """Fair bits from a string of 'H' and 'T'."""
    bits = []
    for i in range(0, len(flips) - 1, 2):
        a, b = flips[i], flips[i + 1]
        if a != b:
            bits.append(a)
    return ''.join(bits)


def expected_flips(p):
    """Expected flips per fair bit, as a Fraction."""
    p = Fraction(p)
    return 1 / (p * (1 - p))
